def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate version and pre-release
        if '-' in version_without_build:
            version_part, prerelease_part = version_without_build.split('-', 1)
        else:
            version_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease.append((0, int(identifier)))
                else:
                    prerelease.append((1, identifier))
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def compare_key(version_with_index):
        version, index = version_with_index
        parsed = parse_version(version)
        major, minor, patch, prerelease = parsed

        # For sorting: versions with prerelease come before those without
        # We use a tuple where prerelease=None sorts after prerelease=[...]
        # So we convert: None -> (1,) and [...] -> (0, [...])
        if prerelease is None:
            prerelease_key = (1,)
        else:
            prerelease_key = (0, prerelease)

        # Return tuple for sorting: (major, minor, patch, prerelease_key, original_index)
        # The original_index maintains input order for equal precedence
        return (major, minor, patch, prerelease_key, index)

    # Enumerate to track original order, sort, then extract just the versions
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [v for _, v in sorted_versions]

